import*as greenlet from"https://cdn.jsdelivr.net/npm/greenlet@1.1.0/+esm";import*as shiki from"https://cdn.jsdelivr.net/npm/shiki@4.4.3/+esm";const SESSION_KEY="blog-enc-password";async function decrypt(e,t){const n=await import("https://cdn.jsdelivr.net/npm/age-encryption@0.3.0/+esm"),o=n.armor.decode(e),s=new n.Decrypter;return s.addPassphrase(t),s.decrypt(o,"text")}const decryptAsync=greenlet.default(decrypt);async function highlight(e,t,n){e.outerHTML=await shiki.codeToHtml(t,{lang:n in shiki.bundledLanguages?n:"text",theme:"catppuccin-mocha"})}async function doUnlock(e,t){const n=e.querySelector("code"),s=await decryptAsync(n.textContent,t);n.textContent=s,e.classList.remove("enc-block","cursor-pointer"),highlight(n.closest("pre"),s,e.dataset.encFormat).catch(e=>console.warn("enc: 语法高亮失败。",e))}async function unlock(e){const n=sessionStorage.getItem(SESSION_KEY);if(n)try{return await doUnlock(e,n)}catch{sessionStorage.removeItem(SESSION_KEY)}const t=window.prompt("请输入密码解锁内容：");if(!t)return;try{await doUnlock(e,t),sessionStorage.setItem(SESSION_KEY,t)}catch(e){console.warn("enc: 解密失败。",e),window.alert("密码不正确或密文已损坏")}}document.addEventListener("click",e=>{const t=e.target.closest(".enc-block");if(!t||e.target.closest(".copy-button"))return;unlock(t)})